export const BANNER_ACHIEVEMENTS = BANNER_ACHIEVEMENT_DATA.map(e => ({
  ...e,
  icon: '📺',
  category: 'banner',
}));

// Meta-achievements
export const BANNER_META_ACHIEVEMENTS = [
  { id: 'the_archivist', name: 'The Archivist', desc: 'Collect all 12 signature scorecards', icon: '📋', category: 'bannerMeta' },
  { id: 'poster_wall', name: 'Poster Wall', desc: 'Collect all 26 team posters', icon: '🖼️', category: 'bannerMeta' },
  { id: 'cooperstown_bobbleheads', name: 'Cooperstown of Bobbleheads', desc: 'Collect every bobblehead, all 26 teams', icon: '👑', category: 'bannerMeta' },
];

// IDs for meta-achievement tracking
export const SCORECARD_ACH_IDS = ["angels_scorecard","athletics_scorecard","bluejays_scorecard","brewers_scorecard","indians_scorecard","mariners_scorecard","orioles_scorecard","rangers_scorecard","royals_scorecard","tigers_scorecard","twins_scorecard","whitesox_scorecard"];
export const POSTER_ACH_IDS = ["angels_poster","astros_poster","athletics_poster","bluejays_poster","braves_poster","brewers_poster","cardinals_poster","cubs_poster","dodgers_poster","expos_poster","giants_poster","indians_poster","mariners_poster","mets_poster","orioles_poster","padres_poster","phillies_poster","pirates_poster","rangers_poster","reds_poster","redsox_poster","royals_poster","tigers_poster","twins_poster","whitesox_poster","yankees_poster"];
export const BOBBLEHEAD_ACH_IDS = ["angels_bobblehead","astros_bobblehead","athletics_bobblehead","bluejays_bobblehead","braves_bobblehead","brewers_bobblehead","cardinals_bobblehead","cubs_bobblehead","dodgers_bobblehead","expos_bobblehead","giants_bobblehead","indians_bobblehead","mariners_bobblehead","mets_bobblehead","orioles_bobblehead","padres_bobblehead","phillies_bobblehead","pirates_bobblehead","rangers_bobblehead","reds_bobblehead","redsox_bobblehead","royals_bobblehead","tigers_bobblehead","twins_bobblehead","whitesox_bobblehead","yankees_bobblehead"];

/**
 * Unlock a banner achievement when its popup is opened.
 * @param {string} achievementId - The banner's achievementId
 * @param {function} unlockFn - The unlockAchievement function from achievements.js
 */
export function unlockBannerAchievement(achievementId, unlockFn) {
  if (!achievementId || !unlockFn) return;
  unlockFn(achievementId);
  // Check meta-achievements
  checkBannerMetaAchievements(unlockFn);
}

/**
 * Check if meta-achievements should unlock based on collected banner achievements.
 */
export function checkBannerMetaAchievements(unlockFn) {
  const stored = JSON.parse(localStorage.getItem('bb84_achievements') || '{}');
  
  if (SCORECARD_ACH_IDS.every(id => stored[id])) unlockFn('the_archivist');
  if (POSTER_ACH_IDS.every(id => stored[id])) unlockFn('poster_wall');
  if (BOBBLEHEAD_ACH_IDS.every(id => stored[id])) unlockFn('cooperstown_bobbleheads');
}

export function isBannerAchievement(id) {
  return BANNER_ACHIEVEMENT_DATA.some(e => e.id === id);
}